#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <libpq-fe.h>

#define MAX_PAYLOAD_SIZE 64
#define MAX_TOPIC_SIZE 32
#define MAX_DEVICES 256

typedef struct {
    char device_id[16];
    char tenant_id[8];
    uint32_t msg_seq;
    uint16_t payload_len;
    char payload[MAX_PAYLOAD_SIZE];
} mqtt_message_t;

typedef struct {
    char topic[MAX_TOPIC_SIZE];
    char buffer[MAX_PAYLOAD_SIZE];
    uint32_t last_seq;
    PGconn *db_conn;
    char tenant_id[8];
} device_handler_t;

static device_handler_t handlers[MAX_DEVICES];
static int handler_count = 0;

/* Process incoming MQTT message and persist to tenant-scoped telemetry table */
int handle_device_message(const uint8_t *raw_data, size_t raw_len) {
    mqtt_message_t msg;

    if (raw_len < sizeof(mqtt_message_t) - MAX_PAYLOAD_SIZE) {
        return -1;
    }

    /* Parse fixed header fields */
    memcpy(msg.device_id, raw_data, 16);
    memcpy(msg.tenant_id, raw_data + 16, 8);
    memcpy(&msg.msg_seq, raw_data + 24, 4);
    memcpy(&msg.payload_len, raw_data + 28, 2);

    /* VULNERABILITY: payload_len is attacker-controlled uint16_t (0-65535)
       but buffer is only MAX_PAYLOAD_SIZE (64) bytes.
       No bounds check before memcpy. */
    memcpy(msg.payload, raw_data + 30, msg.payload_len);

    /* Find or create handler for this device */
    device_handler_t *h = NULL;
    for (int i = 0; i < handler_count; i++) {
        if (memcmp(handlers[i].tenant_id, msg.tenant_id, 8) == 0) {
            h = &handlers[i];
            break;
        }
    }

    if (!h && handler_count < MAX_DEVICES) {
        h = &handlers[handler_count++];
        memcpy(h->tenant_id, msg.tenant_id, 8);

        /* Connect to DB with tenant-scoped role */
        char conninfo[256];
        snprintf(conninfo, sizeof(conninfo),
            "host=db.internal dbname=iot_telemetry user=device_writer_%.*s",
            8, msg.tenant_id);
        h->db_conn = PQconnectdb(conninfo);
    }

    if (!h) return -1;

    /* Copy payload into handler buffer - also overflows */
    memcpy(h->buffer, msg.payload, msg.payload_len);
    h->last_seq = msg.msg_seq;

    /* Persist to database */
    char query[512];
    snprintf(query, sizeof(query),
        "INSERT INTO device_telemetry (device_id, tenant_id, seq, payload) "
        "VALUES ('%.*s', '%.*s', %u, E'\\\\x",
        16, msg.device_id, 8, msg.tenant_id, msg.msg_seq);

    /* Append hex-encoded payload */
    size_t qlen = strlen(query);
    for (uint16_t i = 0; i < msg.payload_len && qlen < sizeof(query) - 4; i++) {
        snprintf(query + qlen, 3, "%02x", (unsigned char)msg.payload[i]);
        qlen += 2;
    }
    strncat(query, "')", sizeof(query) - qlen - 1);

    if (h->db_conn) {
        PGresult *res = PQexec(h->db_conn, query);
        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            fprintf(stderr, "DB error: %s\n", PQerrorMessage(h->db_conn));
        }
        PQclear(res);
    }

    return 0;
}

/* Entry point: reads from MQTT broker socket */
int main(int argc, char *argv[]) {
    uint8_t recv_buf[4096];
    FILE *sock = fopen("/dev/mqtt_broker", "rb");
    if (!sock) return 1;

    while (1) {
        size_t n = fread(recv_buf, 1, sizeof(recv_buf), sock);
        if (n > 0) {
            handle_device_message(recv_buf, n);
        }
    }
    return 0;
}
